#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
import sys as _sys; _sys.path.insert(0, str(Path(__file__).resolve().parent))
from content_generation_guard import assert_generation_allowed  # R12 재발 방지
assert_generation_allowed(__file__)

E={'subnet':'VPC 안에서 IP 주소 범위를 나누고 routing 경계를 만드는 network 구획','virtual-private-cloud':'cloud provider 안에 논리적으로 격리된 virtual network','default-route-any-ipv4':'어떤 IPv4 destination과도 일치하지 않을 때 쓰는 0.0.0.0/0 route','http-303-see-other':'POST 처리 뒤 다른 URL을 GET으로 보게 하는 HTTP redirect status','internet-gateway':'VPC와 internet 사이의 public IPv4 traffic을 연결하는 gateway','outbound-traffic':'resource에서 외부 network로 나가는 traffic','public-subnet':'internet gateway로 가는 route가 있어 public IP resource를 둘 수 있는 subnet','route-table':'destination prefix와 next hop을 연결해 packet 경로를 정하는 rule 집합','cidr':'IP network 주소 범위와 prefix length를 적는 표기','port-22-ssh':'SSH service가 관례적으로 사용하는 TCP port 22','port-80-http':'암호화하지 않은 HTTP service가 관례적으로 사용하는 TCP port 80','elastic-ip':'AWS account에 할당해 instance와 연결할 수 있는 고정 public IPv4 주소','http-200-ok':'HTTP request가 성공적으로 처리됐음을 나타내는 200 status','localhost':'현재 실행 중인 host 자신을 가리키는 loopback 이름','network-error':'DNS, connection, timeout, protocol 등의 실패로 network 요청이 완료되지 않는 상태','nat-gateway':'private subnet resource가 public IPv4로 outbound 연결할 때 source address를 변환하는 gateway','port-localhost':'local host에서 process를 구분하는 port와 loopback 주소의 조합','public-ip':'internet에서 route 가능한 IP address','socket-port':'transport protocol에서 process endpoint를 구분하는 port 번호','fastapi-depends':'FastAPI endpoint에 dependency 값을 주입하는 Depends 선언','fastapi-form':'request form field를 FastAPI parameter로 받게 하는 Form 선언','jinja2':'Python에서 HTML 같은 text output을 template으로 만드는 engine','jinja2-ssr':'Jinja2 template을 server에서 렌더링해 HTML response로 보내는 방식','redirectresponse':'Starlette/FastAPI에서 redirect status와 Location header를 만드는 response','uvicorn':'ASGI application을 실행하는 Python server','asgi':'async Python web application과 server 사이의 interface specification','python-multipart':'multipart/form-data request를 파싱하는 Python package','amazon-ec2':'AWS에서 virtual server instance를 실행하는 compute service','amazon-web-services':'compute, storage, network 등 cloud service를 제공하는 AWS platform','firebase':'authentication, database, hosting 등을 제공하는 Google backend platform','supabase':'PostgreSQL 기반 database, auth, storage를 제공하는 backend platform','amazon-ebs':'EC2 instance에 연결하는 block storage volume service','netlify':'static web site와 serverless 기능을 배포하는 hosting platform','railway':'application과 database를 배포·운영하는 platform service','render':'web service, static site, database를 배포하는 cloud platform','vercel':'frontend와 serverless deployment에 초점을 둔 hosting platform','backend-as-a-service':'인증·database·storage 같은 backend 기능을 managed service로 쓰는 방식','cloud-region':'cloud provider가 resource를 운영하는 지리적 location 단위','deployment':'build artifact를 실행 environment에 배포하고 version을 전환하는 작업','resource-cleanup':'더 이상 쓰지 않는 cloud resource와 data를 제거해 비용·위험을 줄이는 작업','base-image':'container image가 FROM으로 상속하는 시작 filesystem image','docker-attach':'실행 중인 container의 표준 입출력 stream에 연결하는 Docker command','docker-exec':'실행 중인 container 안에서 별도 command를 실행하는 Docker command','docker-info':'Docker daemon과 host 환경 정보를 출력하는 Docker command','docker-ps-docker-ps-a':'실행 중이거나 종료된 container 목록을 보는 Docker command'}
def render(id,tier,term):
 title=term['term_ko'];summary=E[id]+'.';related=['http','tcp'] if id not in {'http-303-see-other','http-200-ok'} else ['http-request-response','redirectresponse']
 out=[f'# {title}','','## 한 줄 설명','',summary,'','## 쉽게 설명하면','',f'`{title}`은(는) 요청이 client에서 service까지 도달하고 배포 환경에서 실행되는 경로를 이해하는 데 쓰입니다.','','## 정확한 설명','',summary+' network boundary, address, port, route, server process의 역할을 서로 구분해야 합니다.']
 if tier=='A':out+=['','## 동작 원리','','request는 name 또는 address를 찾고 route와 gateway를 따라 destination에 도달하며, server process가 해당 port에서 response를 처리합니다.']
 out+=['','## 이 미션에서는 왜 필요한가','','M05와 M12에서 service를 배포하고 외부 request, server response, cloud resource의 연결 상태를 확인하는 기준입니다.','','## 코드 예','',f'```text\n# {title}\nrequest → route → service\n```']
 if tier!='C':out+=['','## 주의할 점 / 경계 조건','','한 network 설정이 정상이어도 DNS, security rule, server process, certificate, application route 중 다른 단계가 실패할 수 있습니다.']
 out+=['','## 관련 용어','']+[f'- `{x}`' for x in related]
 if tier!='C':out+=['','## 흔한 오해','','public address나 열린 port 하나만으로 service 전체가 안전하거나 정상이라는 뜻은 아닙니다.','','## 동료평가 질문','','이 request 경로가 실패했을 때 address, route, port, server 중 어느 순서로 확인하겠습니까?']
 return '\n'.join(out)+'\n'
def main():
 p=json.loads((R/'data/reviews/content-tier-sprint7.json').read_text());b=next(x for x in p['implementation_batches'] if x['id']=='S7-B07');it={x['term_id']:x for x in p['items']};m=json.loads((R/'data/curated/glossary-master-v0.1.yaml').read_text());by={x['id']:x for x in m['terms']};assert set(b['term_ids'])==set(E) and len(E)==45
 for id in b['term_ids']:(R/'content/terms'/f'{id}.md').write_text(render(id,it[id]['tier'],by[id]),encoding='utf-8');by[id]['content_status']='drafted'
 (R/'data/curated/glossary-master-v0.1.yaml').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');print('Wrote 45 S7-B07 term files.')
if __name__=='__main__':main()
